// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-03.md
// @data: идёт в проекте data; устройство — iPhone 13 Mini (WebKit) через test.use ниже.
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, cleanupPost, deletePostViaUi, form, isPostCreate, openComposer, qaText, tap, type Published } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Публикация текста: спиннер, повторный тап не дублирует, возврат в ленту, пост виден один раз; затем удаление @iphone @data (#1ff0f4)', async ({ page }) => {
    test.setTimeout(120_000);
    const text = qaText('publish');
    let published: Published | undefined;
    let deleted = false;
    let posts = 0;
    page.on('request', (r) => { if (isPostCreate(r)) posts++; });

    // Держим POST /rest/v1/posts, пока не проверим состояние загрузки (без фиксированных пауз).
    let release!: () => void;
    const held = new Promise<void>((r) => (release = r));
    await page.route(/\/rest\/v1\/posts(\?|$)/, async (route) => {
      if (route.request().method() === 'POST') await held;
      await route.continue();
    });

    try {
      // 1. Лента → «פוסט חדש», ввести текст
      await openComposer(page);
      const f = form(page);
      await f.text.fill(text);
      await expect(f.publish).toBeEnabled();

      // 2. «לפרסם» → во время сохранения кнопка disabled со спиннером (AC5); повторный тап
      const reqP = page.waitForRequest(isPostCreate);
      const resP = page.waitForResponse((r) => isPostCreate(r.request()));
      await tap(page, f.publish);
      const req = await reqP;
      expect(req.postDataJSON()).toMatchObject({ body: text });
      const progress = page.getByRole('progressbar');
      await expect(progress).toBeVisible();
      const busyBtn = page.getByRole('button').filter({ has: progress });
      await expect(busyBtn).toBeDisabled();
      await tap(page, busyBtn);

      // 3. Отпускаем запрос → 201, переход в ленту (AC4, AC8)
      release();
      const res = await resP;
      expect(res.status()).toBe(201);
      const body = await res.json();
      published = { id: String((Array.isArray(body) ? body[0] : body).id), text, rest: new URL(res.url()).origin, headers: await req.allHeaders() };
      await page.waitForURL(/\/social/);
      await expect(page.getByText(text, { exact: true })).toHaveCount(1);
      expect(posts, 'ровно один POST /rest/v1/posts (без дубля)').toBe(1);

      // 4. Очистка: удалить пост через меню
      await page.unroute(/\/rest\/v1\/posts(\?|$)/);
      await deletePostViaUi(page, text);
      deleted = true;
    } finally {
      release?.();
      if (published && !deleted) await cleanupPost(page, published);
      await saveSession(page, 'free');
    }
  });
});
